effects.fragment:
float l__wave_a = sin(v_tex_coord.y * 42.0 + u_time * u__speed * 3.1);
float l__wave_b = sin((v_tex_coord.x + v_tex_coord.y) * 57.0 - u_time * u__speed * 2.3);
float l__caustic = pow(clamp(0.5 + 0.25 * l__wave_a + 0.25 * l__wave_b, 0.0, 1.0), 3.0);
vec3 l__submerged = mix(gl_FragColor.rgb, gl_FragColor.rgb * u__water_color, u__depth);
l__submerged += u__water_color * l__caustic * u__caustics;
gl_FragColor.rgb = mix(gl_FragColor.rgb, l__submerged, u__intensity);

float l__height = clamp(1.0 - v_tex_coord.y, 0.0, 1.0);
float l__air = mix(1.0, pow(l__height, 1.0 + u__falloff), u__falloff * 0.5);
vec3 l__warm = gl_FragColor.rgb * u__warmth + u__warmth * u__haze * l__air;
gl_FragColor.rgb = mix(gl_FragColor.rgb, l__warm, u__intensity);

float l__pulse = 0.5 + 0.5 * sin(u_time * u__speed + v_tex_coord.x * 2.4);
float l__luma = dot(gl_FragColor.rgb, vec3(0.2126, 0.7152, 0.0722));
vec3 l__dream = mix(vec3(l__luma), gl_FragColor.rgb * u__pastel, 0.68);
l__dream += u__pastel * u__lift * (0.65 + 0.35 * l__pulse) * (1.0 - l__luma);
gl_FragColor.rgb = mix(gl_FragColor.rgb, l__dream, u__intensity);
